#!/bin/bash
# FILENAME: 3a_cellpose_gpu.sh
# DESCRIPTION: GPU step: cellpose segmentation backend only (raw output); post-processing is 3b.
# Generated by slurm_scripts/script.py (Anvil). Step bodies follow aws_templates/aws_s3_template/.

#SBATCH -A mcb130189-gpu
#SBATCH -p gpu
#SBATCH -t {T_CELLPOSE_GPU}
#SBATCH --nodes=1
#SBATCH --gpus-per-node=1
#SBATCH --ntasks=1
#SBATCH --cpus-per-task=64
#SBATCH --mem=256gb
#SBATCH -J cellpose_gpu_{EXP_N}_{REG_N}
#SBATCH -o {LOG_DIR}/3a_cellpose_gpu_{EXP_N}_{REG_N}.out
#SBATCH -e {LOG_DIR}/3a_cellpose_gpu_{EXP_N}_{REG_N}.out

module purge
module load modtree/gpu
module load ngc
module load mpc
module load cuda/12.0.1
module load pytorch/21.09-py3
module list

# Fail fast from here on: any non-zero exit aborts the job, so --dependency=afterok in chain.sh stops
# downstream steps. Module loads above stay non-fatal (not every module exists on every node type).
set -eo pipefail  # no -u: Lmod module functions read unset variables

export PATH="/home/x-aklein2/.pixi/bin:$PATH"
export SLURM_TMPDIR="${{SLURM_TMPDIR:-${{TMPDIR:-/tmp}}}}"
export PIXI_HOME="${{SLURM_TMPDIR}}/pixi_home_${{SLURM_JOB_ID:-$$}}"
export PIXI_CACHE_DIR="${{SLURM_TMPDIR}}/pixi_cache_${{SLURM_JOB_ID:-$$}}"   # per-job, node-local: no sharing between jobs
export RATTLER_CACHE_DIR="$PIXI_CACHE_DIR"
mkdir -p "$PIXI_HOME" "$PIXI_CACHE_DIR" "$RATTLER_CACHE_DIR"

# Run from a copy of SPIDA: edits to the source tree cannot reach a running job.
WORKDIR="${{SLURM_TMPDIR}}/spida_${{SLURM_JOB_ID:-$$}}"
# copy + env + cache are ~30 GB; the node only purges /tmp at the next other user's job start
trap 'cd /; rm -rf "$WORKDIR" "$PIXI_HOME" "$PIXI_CACHE_DIR"' EXIT
rsync -a --delete --exclude '.pixi/envs' "{SPIDA_ROOT}/" "$WORKDIR/"
cd "$WORKDIR"
# download into the local cache; if that fails (e.g. no network), retry from the shared project cache
pixi install --frozen -e cellpose || \
    PIXI_CACHE_DIR=/anvil/projects/x-mcb130189/aklein/.cache/rattler/cache \
    RATTLER_CACHE_DIR=/anvil/projects/x-mcb130189/aklein/.cache/rattler/cache \
    pixi install --frozen -e cellpose

# --- Compute ---
# IMAGE_EXT is set by script_aws.py (--force_2d_segmentation flag).
# .decon.tif = all deconvolved planes; _z3.decon.tif = the middle z-slice (2D segmentation).
IMAGE_EXT="{IMAGE_EXT}"

# Tiling and any other method kwargs script_aws.py chose. Empty means the whole
# region goes to the GPU in one model.eval call. Deliberately unquoted below so
# it word-splits into separate arguments (and to nothing when empty).
SEG_EXTRA_ARGS="{SEG_EXTRA_ARGS}"

echo -e "\nRunning Cellpose segmentation (backend only) on region {REGION} of experiment {EXPERIMENT}\n"
echo "seg_mode={SEG_MODE}  model={CELLPOSE_MODEL}  extra: ${{SEG_EXTRA_ARGS:-<none>}}"
# Raw boundaries land in the segmentation store under {EXPERIMENT}/{REGION}/{CELLPOSE_PREFIX}.
# Stain images come from the deconvolved planes; tissue mask and transform from images/.
pixi run --frozen -e cellpose \
    python -m spida.S.cli --config {CONFIG_PATH} \
    segment-region \
    cellpose \
    --exp {EXPERIMENT} \
    --reg {REGION} \
    --prefix_name {CELLPOSE_PREFIX} \
    --image_dir {DECON_DIR} \
    {TISSUE_MASK_ARG}{OVERWRITE_ARG} \
    --seg_mode={SEG_MODE} \
    --model={CELLPOSE_MODEL} \
    --scale=4 \
    --image_ext=$IMAGE_EXT \
    --nuc_stain_name=DAPI \
    --cyto_stain_name=PolyT \
    --flow_threshold=0 \
    --cellprob_threshold=-2 \
    --tile_norm_blocksize=2960 \
    $SEG_EXTRA_ARGS
